def seed_legal_catalog(apps, schema_editor):
    PracticeArea = apps.get_model("office", "PracticeArea")
    MatterType = apps.get_model("office", "MatterType")
    for area_order, (name, slug, description, icon, matter_types) in enumerate(AREA_CATALOG, start=1):
        area, _ = PracticeArea.objects.update_or_create(
            slug=slug,
            defaults={
                "name": name,
                "description": description,
                "icon": icon,
                "sort_order": area_order,
                "is_active": True,
            },
        )
        for type_order, (type_name, type_slug, focus_step, documents) in enumerate(matter_types, start=1):
            MatterType.objects.update_or_create(
                practice_area=area,
                slug=type_slug,
                defaults={
                    "name": type_name,
                    "description": focus_step,
                    "workflow_steps": [
                        "Realizar triagem e checagem de conflito de interesses",
                        "Validar escopo, documentos e responsáveis",
                        focus_step,
                        "Definir estratégia, riscos e próximos marcos",
                        "Registrar andamento e comunicar o cliente",
                    ],
                    "required_documents": documents,
                    "sort_order": type_order,
                    "is_active": True,
                },
            )
    Organization = apps.get_model("core", "Organization")
    LegalCase = apps.get_model("office", "LegalCase")
    WorkItem = apps.get_model("office", "WorkItem")
    demo_office = Organization.objects.filter(slug="demo-office").first()
    contract_area = PracticeArea.objects.filter(slug="contratos").first()
    contract_type = MatterType.objects.filter(
        practice_area=contract_area,
        slug="revisao-negociacao",
    ).first()
    if demo_office and contract_area and contract_type:
        demo_cases = LegalCase.objects.filter(
            organization_id=demo_office.pk,
            title="Revisão contratual empresarial",
        )
        demo_cases.update(
            practice_area_id=contract_area.pk,
            matter_type_id=contract_type.pk,
            nature="advisory",
            stage="in_progress",
        )
        demo_case = demo_cases.first()
        if demo_case:
            WorkItem.objects.filter(
                organization_id=demo_office.pk,
                title="Revisar contrato de prestação de serviços",
                case_id__isnull=True,
            ).update(case_id=demo_case.pk)


def remove_legal_catalog(apps, schema_editor):
    PracticeArea = apps.get_model("office", "PracticeArea")
    PracticeArea.objects.filter(slug__in=[item[1] for item in AREA_CATALOG]).delete()


